import { createAddressController, deleteAddressController, getAddressDefaultController, getAllAddressByUserController, updateAddressController } from "#controllers/address.controller";
import { VerifyToken } from "#middlewares/Auth";
import { CheckRole } from "#middlewares/CheckRole";
import { Validate } from "#middlewares/Validate";
import { createAddressSchema } from "#validations/address.validation";
import { Router } from "express";
const router = Router();
router.use(VerifyToken);
router.use(CheckRole("CUSTOMER"));
router.post("/", Validate(createAddressSchema), createAddressController);
router.get("/address-default", getAddressDefaultController);
router.get("/", getAllAddressByUserController);
router.put("/:addressId", updateAddressController);
router.delete("/:addressId", deleteAddressController);
export default router;
